// BioCanvas core — MIT. Pure scene operations and interoperable export formats.
export const WIDTH=1000, HEIGHT=650;
export const escapeXML=s=>String(s??'').replace(/[<>&"']/g,c=>({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":'&apos;'}[c]));
export const uid=()=>globalThis.crypto?.randomUUID?.()||`n${Date.now()}${Math.random().toString(36).slice(2)}`;
export const clone=x=>JSON.parse(JSON.stringify(x));
export function node(type,opts={}){return {id:uid(),type,x:420,y:270,w:100,h:100,label:'',color:'#527d63',fontSize:15,rotation:0,...opts};}
export function edge(a,b,opts={}){return{id:uid(),from:a,to:b,color:'#7e9781',label:'',...opts};}
export function connection(a,b){const ac={x:a.x+a.w/2,y:a.y+a.h/2},bc={x:b.x+b.w/2,y:b.y+b.h/2};const dx=bc.x-ac.x,dy=bc.y-ac.y;
 const anchor=(n,c,s)=>{if(!dx&&!dy)return c;const labelPad=n.type==='asset'&&dy*s>0&&n.label?26+(n.label.split('\n').length-1)*n.fontSize*1.5:0;const k=Math.min((n.w/2+9)/Math.max(Math.abs(dx),.0001),(n.h/2+9+labelPad)/Math.max(Math.abs(dy),.0001));return{x:c.x+dx*k*s,y:c.y+dy*k*s}};return[anchor(a,ac,1),anchor(b,bc,-1)];}
export function validateScene(s){if(!s||s.format!=='biocanvas'||s.version!==1||!Array.isArray(s.nodes)||!Array.isArray(s.edges)||s.nodes.length>500||s.edges.length>1000)throw Error('不是支持的 BioCanvas 项目文件（v1）。');
 const ids=new Set();for(const n of s.nodes){if(!n||!['asset','text','box'].includes(n.type)||typeof n.id!=='string'||ids.has(n.id))throw Error('项目中有无效元素。');ids.add(n.id);for(const k of ['x','y','w','h','fontSize','rotation'])if(!Number.isFinite(n[k])||Math.abs(n[k])>100000)throw Error('元素尺寸无效。');if(n.w<=0||n.h<=0||n.fontSize<1||n.fontSize>200)throw Error('元素尺寸无效。');if(typeof n.label!=='string'||n.label.length>20000)throw Error('文字无效。');if(!/^#[\da-f]{6}$/i.test(n.color))throw Error('颜色无效。');if(n.type==='asset'&&(typeof n.assetId!=='string'||n.assetId.length>200))throw Error('素材标识无效。');}
 const eids=new Set();for(const e of s.edges){if(!e||typeof e.id!=='string'||ids.has(e.id)||eids.has(e.id)||!ids.has(e.from)||!ids.has(e.to)||typeof e.label!=='string'||!/^#[\da-f]{6}$/i.test(e.color))throw Error('连线数据无效。');eids.add(e.id);}if(s.customAssets&&(!Array.isArray(s.customAssets)||s.customAssets.length>100))throw Error('自定义素材无效。');for(const a of s.customAssets||[])if(!a||typeof a.id!=='string'||typeof a.svg!=='string'||a.svg.length>2000000)throw Error('自定义素材无效。');if(typeof s.title!=='string'||s.title.length>300)throw Error('项目标题无效。');return s;}
export function emptyScene(title='未命名图稿'){return{format:'biocanvas',version:1,title,nodes:[],edges:[],customAssets:[]};}
function textLines(label,x,y,size,color,anchor='middle'){return `<text x="${x}" y="${y}" text-anchor="${anchor}" fill="${escapeXML(color)}" font-family="Arial, Microsoft Yahei, sans-serif" font-size="${size}">${String(label).split('\n').map((line,i)=>`<tspan x="${x}" dy="${i?size*1.5:0}">${escapeXML(line)}</tspan>`).join('')}</text>`;}
export function nodeMarkup(n,assets){let body='';if(n.type==='asset'){const a=assets.get(n.assetId);body=a?`<svg x="0" y="0" width="${n.w}" height="${n.h}" viewBox="${escapeXML(a.viewBox)}" preserveAspectRatio="xMidYMid meet">${a.inner}</svg>`:`<rect width="${n.w}" height="${n.h}" fill="#f2f3ee"/><text x="10" y="30" font-size="13">素材缺失</text>`;body+=textLines(n.label,n.w/2,n.h+26,n.fontSize,'#3c5143');}
 if(n.type==='box'){body=`<rect width="${n.w}" height="${n.h}" rx="12" fill="${n.color}" fill-opacity=".1" stroke="${n.color}" stroke-width="1.5"/>`+textLines(n.label,n.w/2,n.h/2-(n.label.split('\n').length-1)*n.fontSize*.75+n.fontSize*.35,n.fontSize,'#344b3d');}
 if(n.type==='text')body=textLines(n.label,0,n.fontSize,n.fontSize,n.color,'start');return `<g class="node" data-id="${escapeXML(n.id)}" transform="translate(${n.x} ${n.y}) rotate(${n.rotation} ${n.w/2} ${n.h/2})">${body}</g>`;}
export function edgeMarkup(e,nodes,hit=false){const a=nodes.find(n=>n.id===e.from),b=nodes.find(n=>n.id===e.to);if(!a||!b)return'';const[p,q]=connection(a,b);const line=`M${p.x},${p.y} L${q.x},${q.y}`;return `<g class="edge" data-id="${escapeXML(e.id)}">${hit?`<path d="${line}" stroke="transparent" stroke-width="16" fill="none"/>`:''}<path d="${line}" fill="none" stroke="${escapeXML(e.color)}" stroke-width="1.8" marker-end="url(#arrow)"/>${textLines(e.label,(p.x+q.x)/2,(p.y+q.y)/2-9,12,e.color)}</g>`;}
export const defs='<defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M 1 1 L 9 5 L 1 9" fill="none" stroke="#7e9781" stroke-width="1.5"/></marker></defs>';
export function credits(scene,assets){return [...new Set(scene.nodes.filter(n=>n.type==='asset').map(n=>n.assetId))].map(id=>{const a=assets.get(id);return a?{name:a.name,author:a.author,license:a.license,source:a.source,licenseUrl:a.licenseUrl,modifications:[a.modifications,'Sanitized static SVG; internal identifiers rewritten; placement and sizing may be changed.'].filter(Boolean).join(' ')}: {name:id,license:'missing'};});}
export function exportSVG(scene,assets){return `<?xml version="1.0" encoding="UTF-8"?>\n<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" width="1000" height="650" viewBox="0 0 1000 650"><title>${escapeXML(scene.title)}</title><metadata>${escapeXML(JSON.stringify({generator:'BioCanvas 0.2',assets:credits(scene,assets)}))}</metadata>${defs}<rect width="1000" height="650" fill="white"/>${scene.edges.map(e=>edgeMarkup(e,scene.nodes)).join('')}${scene.nodes.map(n=>nodeMarkup(n,assets)).join('')}</svg>`;}
export function exportDrawio(scene,assets){let cells='<mxCell id="0"/><mxCell id="1" parent="0"/>';for(const n of scene.nodes){let style=`rounded=1;whiteSpace=wrap;html=0;fontSize=${n.fontSize};rotation=${n.rotation};fontColor=${n.color};`;
 if(n.type==='asset'){const a=assets.get(n.assetId);if(a){const svg=`<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" viewBox="${a.viewBox}">${a.inner}</svg>`;style+=`shape=image;verticalLabelPosition=bottom;verticalAlign=top;imageAspect=1;image=data:image/svg+xml,${encodeURIComponent(svg)};`;}}
 else if(n.type==='text')style+='text;fillColor=none;strokeColor=none;align=left;verticalAlign=top;';else style+=`fillColor=#f2f6ef;strokeColor=${n.color};`;
 cells+=`<mxCell id="${escapeXML(n.id)}" value="${escapeXML(n.label)}" style="${escapeXML(style)}" vertex="1" parent="1"><mxGeometry x="${n.x}" y="${n.y}" width="${n.w}" height="${n.h}" as="geometry"/></mxCell>`;}
 for(const e of scene.edges)cells+=`<mxCell id="${escapeXML(e.id)}" value="${escapeXML(e.label)}" style="endArrow=block;html=0;strokeColor=${e.color};" edge="1" source="${escapeXML(e.from)}" target="${escapeXML(e.to)}" parent="1"><mxGeometry relative="1" as="geometry"/></mxCell>`;
 return `<?xml version="1.0" encoding="UTF-8"?><mxfile host="BioCanvas"><diagram name="${escapeXML(scene.title)}" id="biocanvas"><mxGraphModel page="1" pageWidth="1000" pageHeight="650"><root>${cells}</root></mxGraphModel></diagram></mxfile>`;}
export function template(kind,locale='zh'){let s=emptyScene(kind==='pcr'?(locale==='en'?'PCR & Gel Analysis':'PCR 与凝胶分析'):kind==='blank'?(locale==='en'?'Untitled Figure':'未命名图稿'):(locale==='en'?'Bacterial Transformation · Workflow':'细菌转化 · 实验流程'));if(kind==='blank')return s;
 s.nodes.push(node('text',{x:66,y:43,w:870,h:36,label:kind==='pcr'?'PCR amplification & analysis':'Bacterial transformation',fontSize:27,color:'#344f3f'}));
 s.nodes.push(node('text',{x:67,y:91,w:850,h:20,label:locale==='en'?'METHODS OVERVIEW   /   Experimental workflow · Adapt for your protocol':'METHODS OVERVIEW   /   实验流程示意 · 请按实际实验修改',fontSize:10,color:'#94a089'}));
 const data=kind==='pcr'?(locale==='en'?[['DNA_double_helix','01  Template DNA'],['Pipette','02  Reaction Setup'],['qpcr_machine','03  PCR Amplification'],['agarose-gel','04  Gel Analysis']]:[['DNA_double_helix','01  模板 DNA'],['Pipette','02  配制反应体系'],['qpcr_machine','03  PCR 扩增'],['agarose-gel','04  凝胶分析']]):(locale==='en'?[['plasmid-3','01  Plasmid DNA\nPrepare vector'],['generic-bacterium','02  Competent Cells\nAdd plasmid'],['water_bath','03  Transformation\nFollow protocol'],['erlenmeyer_filled','04  Recovery\nAdd recovery broth'],['isolation','05  Plating\nSelective medium'],['incubator','06  Colony Screening\nIncubate & record']]:[['plasmid-3','01  质粒 DNA\n准备转化材料'],['generic-bacterium','02  感受态细胞\n加入质粒'],['water_bath','03  转化处理\n按实验方案操作'],['erlenmeyer_filled','04  复苏培养\n添加复苏培养基'],['isolation','05  涂布培养\n使用选择性培养基'],['incubator','06  菌落筛选\n培养并记录结果']]);
 const diagramNodes=[];data.forEach(([assetId,label],i)=>{let x,y;if(kind==='pcr'){x=85+i*235;y=252;}else{x=130+(i<3?i:5-i)*310;y=i<3?170:397;}const n=node('asset',{assetId,x,y,w:110,h:105,label,fontSize:14});s.nodes.push(n);diagramNodes.push(n);});diagramNodes.forEach((n,i)=>{if(i)s.edges.push(edge(diagramNodes[i-1].id,n.id));});s.nodes.push(node('text',{x:66,y:609,w:870,h:18,label:locale==='en'?'FIG. 01     Workflow template · Adapt experimental conditions to actual lab protocol':'FIG. 01     实验步骤模板  ·  条件与参数以实际实验记录为准',fontSize:10,color:'#9ca68f'}));return s;}
